import assert from "node:assert/strict";
import test from "node:test";
import {
  advanceShots,
  fireWeapon,
  isCheckpointShot,
  isShot,
  type Shot,
} from "./index.js";

// Generated by probe.py from C-Dogs v1.06, pin and harness documented in REFERENCE.md.
const trace = [
  "6d4a45c5",
  "670b3814",
  "36d21dfd",
  "d3ef7630",
  "20a51363",
  "4d5031a4",
  "8cd061c9",
  "dfb8735d",
  "75835916",
  "cd0124e5",
  "cadbf9d5",
  "36920c65",
  "0bee774d",
  "56e53824",
  "38291c25",
  "f6e10f35",
];
for (const [weapon, expected] of trace.entries()) {
  test(`DOS v1.06 weapon ${weapon}: 8 facings, open and obstructed, 285 updates`, () => {
    let hash = 2166136261;
    const mix = (value: number) => {
      hash = Math.imul(hash ^ value, 16777619) >>> 0;
    };
    const sample = (shots: Shot[]) => {
      for (const s of shots) {
        for (const field of [
          s.x * 256,
          s.y * 256,
          s.dx * 256,
          s.dy * 256,
          s.z,
          s.dz,
          s.age,
          s.range,
          s.power,
          s.radiusX,
          s.radiusY,
        ])
          mix(field);
        assert.ok(isShot(s));
      }
      mix(shots.length);
    };
    for (const obstructed of [false, true]) {
      const env = {
        random: () => 4,
        wall: (x: number, y: number) =>
          obstructed && (x < 448 || x >= 576 || y < 336 || y >= 432),
        hit: (_s: Shot, x: number, y: number) =>
          obstructed && x === 537 && y >= 374 && y <= 397,
        nearActor: (x: number, y: number) =>
          Math.abs(Math.floor(x / 16) - 32) <= 1 &&
          Math.abs(Math.floor(y / 12) - 32) <= 1,
      };
      for (let dir = 0; dir < 8; dir++) {
        const fire = fireWeapon(weapon, "p", 512, 384, dir, env.random);
        mix(fire.lock);
        mix(fire.cost);
        let shots = fire.shots;
        sample(shots);
        for (let tick = 1; tick <= 285; tick++) {
          shots = advanceShots(shots, env);
          sample(shots);
        }
      }
    }
    assert.equal(hash.toString(16).padStart(8, "0"), expected);
  });
}
test("snapshot validation refuses malformed shot data", () => {
  const [p] = fireWeapon(4, "p", 512, 384, 2, () => 4).shots;
  assert.ok(isShot(p));
  for (const delta of [
    { power: Infinity },
    { range: 211 },
    { x: 0.1 },
    { dy: NaN },
    { kind: "missing" },
    { weapon: -1 },
    { always: null },
  ])
    assert.equal(isShot({ ...p, ...delta }), false);
});

test("only the checkpoint guard rejects unrelated shot metadata", () => {
  const [shot] = fireWeapon(1, "player-0", 512, 384, 0, () => 4).shots;
  assert.ok(isCheckpointShot(shot));
  const withMetadata = { ...shot, note: "observed" };
  assert.ok(isShot(withMetadata));
  assert.equal(isCheckpointShot(withMetadata), false);
});
